static _CLG_NF4_VAR_1_SPLINE: OnceLock<RectBivariateSpline> = OnceLock::new();

/// Returns the degree-(3,3) interpolating spline over `CLg_nf4_var-1`.
///
/// The spline is constructed on the **first call only**; every subsequent
/// call returns a reference to the same object at zero cost.  Safe to call
/// from multiple threads simultaneously — `OnceLock` guarantees exactly-once
/// initialisation even under concurrent access.
#[inline]
pub fn clg_nf4_var_1_spline() -> &'static RectBivariateSpline {
    _CLG_NF4_VAR_1_SPLINE.get_or_init(|| {
        RectBivariateSpline::new(
            &CLG_NF4_VAR_1_X,
            &CLG_NF4_VAR_1_Y,
            &CLG_NF4_VAR_1_BODY,
            3,
            3,
        )
    })
}
